import os
for p in ['experiments/e2/agent3_metaplectic_final.txt','experiments/e2/agent2_metaplectic_filtration.txt','experiments/e1/agent4_degree2_relations.md','experiments/e1/agent4_explicit_degree4_conflict.md']:
 print('\nFILE',p); print(open(p).read()[:24000])
print('\nSEARCH')
for e in ['e1','e2','e3']:
 for root,ds,fs in os.walk('experiments/'+e):
  for f in fs:
   if f.endswith(('.md','.txt')):
    p=os.path.join(root,f); lines=open(p,errors='replace').readlines()
    for i,l in enumerate(lines):
     if any(t in l.lower() for t in ['stabiliz','stabilis','dummy','extra index','spare index']):
      print(p,i+1, ''.join(lines[max(0,i-1):i+2])[:1400])

